INSERT INTO interview_questions (company_id, role_type, question_text, question_type, difficulty_level, source, source_url, confidence_score) VALUES
('1a2b3c4d-5e6f-7a8b-9c0d-1e2f3a4b5c6d', 'backend', 'Implement a rate limiter in memory supporting token bucket algorithm for API endpoints.', 'coding', 'medium', 'hn', 'https://news.ycombinator.com', 0.80),
('1a2b3c4d-5e6f-7a8b-9c0d-1e2f3a4b5c6d', 'backend', 'Find bugs and write unit tests for a pre-written micro-service representing a payment ledger.', 'coding', 'hard', 'github', 'https://github.com', 0.90),
('2b3c4d5e-6f7a-8b9c-0d1e-2f3a4b5c6d7e', 'backend', 'Explain what happens when you type stripe.com in a web browser and hit enter.', 'system-design', 'medium', 'manual', NULL, 0.95),
('4d5e6f7a-8b9c-0d1e-2f3a-4b5c6d7e8f9a', 'backend', 'Design a simplified parking lot system. Provide low-level design class diagrams and write working code in 90 minutes.', 'coding', 'hard', 'manual', NULL, 0.90),
('3c4d5e6f-7a8b-9c0d-1e2f-3a4b5c6d7e8f', 'frontend', 'Build a simple drag-and-drop file uploader using custom React hooks and style it with Tailwind.', 'coding', 'medium', 'github', NULL, 0.85);
INSERT INTO hiring_notes (company_id, note_type, note_text, source, confidence_score) VALUES
('1a2b3c4d-5e6f-7a8b-9c0d-1e2f3a4b5c6d', 'process', 'Stripe conducts a unique "bug hunt" interview round where you are given an existing repository with failing tests or design issues and you must debug it.', 'manual', 0.95),
('4d5e6f7a-8b9c-0d1e-2f3a-4b5c6d7e8f9a', 'process', 'Razorpay focuses heavily on machine coding. They look for clean, modular, and runnable code with OOP principles rather than just basic algorithmic correctness.', 'manual', 0.95);
